<?php
require_once __DIR__.'/functions.php';require_once __DIR__.'/app_init.php';$pdo=dogvive_db();$message='';$error='';$token=(string)($_GET['token']??'');
$pdo->exec("CREATE TABLE IF NOT EXISTS restablecimiento_clave (id INT AUTO_INCREMENT PRIMARY KEY,id_usuario INT NOT NULL,token_hash CHAR(64) NOT NULL,expira DATETIME NOT NULL,usado TINYINT(1) NOT NULL DEFAULT 0,creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(token_hash)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['solicitar'])){try{$email=strtolower(trim((string)($_POST['correo']??'')));if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Escribe un correo válido.');$q=$pdo->prepare('SELECT id_usuario,Correo FROM usuario WHERE Correo=? LIMIT 1');$q->execute([$email]);$u=$q->fetch();$message='Si el correo está registrado, se generará un enlace de restablecimiento. Revisa tu correo si el servidor tiene el envío de email configurado.';if($u){$raw=bin2hex(random_bytes(32));$hash=hash('sha256',$raw);$expires=date('Y-m-d H:i:s',time()+1800);$ins=$pdo->prepare('INSERT INTO restablecimiento_clave (id_usuario,token_hash,expira) VALUES (?,?,?)');$ins->execute([$u['id_usuario'],$hash,$expires]);$link=base_url().'/restablecer-contrasena.php?token='.$raw;$subject='Restablecer contraseña de Dog Vibe';$body="Usa este enlace para cambiar tu contraseña (válido por 30 minutos):\nhttp://".($_SERVER['HTTP_HOST']??'localhost').$link;@mail($email,$subject,$body,'From: no-reply@dogvibe.local');if(in_array($_SERVER['HTTP_HOST']??'',['localhost','127.0.0.1','localhost:80','localhost:8080'],true))$_SESSION['dogvive_dev_reset_link']=$link;}}catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'No se pudo procesar la solicitud.';}}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['cambiar'])){try{$raw=(string)($_POST['token']??'');$pw=(string)($_POST['password']??'');$confirm=(string)($_POST['confirmar']??'');if(strlen($pw)<8)throw new RuntimeException('La contraseña debe tener al menos 8 caracteres.');if($pw!==$confirm)throw new RuntimeException('Las contraseñas no coinciden.');$q=$pdo->prepare('SELECT * FROM restablecimiento_clave WHERE token_hash=? AND usado=0 AND expira>NOW() ORDER BY id DESC LIMIT 1');$q->execute([hash('sha256',$raw)]);$row=$q->fetch();if(!$row)throw new RuntimeException('El enlace expiró o ya fue utilizado. Solicita uno nuevo.');$pdo->beginTransaction();$u=$pdo->prepare('UPDATE usuario SET `Contraseña`=? WHERE id_usuario=?');$u->execute([password_hash($pw,PASSWORD_DEFAULT),$row['id_usuario']]);$done=$pdo->prepare('UPDATE restablecimiento_clave SET usado=1 WHERE id=?');$done->execute([$row['id']]);$pdo->commit();$message='Contraseña actualizada. Ya puedes iniciar sesión.';$token='';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'No se pudo cambiar la contraseña.';}}
render_header('Restablecer contraseña');page_wrap_start('Restablecer contraseña','Recupera el acceso a tu cuenta.');if($message)echo '<div class="notice">'.e($message).'</div>';if($error)echo '<div class="error-box">'.e($error).'</div>';if($token!==''): ?>
<div class="form-box card" style="max-width:820px"><form method="post"><input type="hidden" name="token" value="<?= e($token) ?>"><label>Nueva contraseña<input type="password" name="password" minlength="8" required></label><label>Confirmar contraseña<input type="password" name="confirmar" minlength="8" required></label><button class="btn btn-primary full" name="cambiar" value="1" type="submit">Guardar nueva contraseña</button></form></div>
<?php else: ?><div class="form-box card" style="max-width:820px"><form method="post"><label>Correo electrónico<input type="email" name="correo" placeholder="tu@correo.com" required></label><button class="btn btn-primary full" type="submit" name="solicitar" value="1">Solicitar enlace</button></form><?php if(!empty($_SESSION['dogvive_dev_reset_link'])): ?><div class="notice" style="margin-top:16px">Modo local de desarrollo: el envío de correo puede no estar configurado. Enlace de prueba: <a href="<?= e((string)$_SESSION['dogvive_dev_reset_link']) ?>">Restablecer contraseña</a></div><?php unset($_SESSION['dogvive_dev_reset_link']);endif; ?></div><?php endif; ?><?php page_wrap_end();echo '</body></html>';
